### Validating data




::: {.cell layout-align="center"}

```{.r .cell-code}
library(assertr)
library(tidyverse)
library(rlang)

data_checks <- function(data,
                        metadata_path = NULL,
                        bounded_cols = NULL,
                        bounds = c(1, 30),
                        treatment_levels = c("A", "B"),
                        just_warn = TRUE) {
  handler <- if (just_warn) assertr::just_warn else assertr::error_stop

  # Read metadata if provided
  metadata <- if (!is.null(metadata_path)) {
    readxl::read_excel(metadata_path, sheet = "Data Dictionary")
  } else {
    NULL
  }

  # Basic column presence check
  if (!is.null(metadata)) {
    required_cols <- metadata |> pull(Name)
    data <- data |> verify(has_all_names(required_cols), error_fun = handler)

    # Type check helper
    check_types <- function(d, m) {
      out <- tibble(
        variable = m$Name,
        expected = m$Type,
        actual   = map_chr(m$Name, ~ if (.x %in% names(d)) class(d[[.x]])[1] else NA_character_),
        match    = tolower(expected) == tolower(actual)
      )
      print(out)
      invisible(out)
    }

    check_types(data, metadata)
  }

  # Non-missing
  if (ncol(data) > 0) {
    data <- data |> assert(not_na, !!!syms(names(data)), error_fun = handler)
  }

  # Treatment
  if ("treatment" %in% names(data)) {
    data <- data |> assert(in_set(treatment_levels), treatment, error_fun = handler)
  }

  # Bounded numeric
  if (!is.null(bounded_cols)) {
    data <- data |> assert(within_bounds(bounds[1], bounds[2]), !!!syms(bounded_cols), error_fun = handler)
  }

  # Eggs logic check
  if (all(c("eggs_hatched", "eggs_laid") %in% names(data))) {
    data <- data |> verify(eggs_hatched <= eggs_laid, error_fun = handler)
  }

  return(data)
}
```
